#!/usr/bin/env bash
# B4a = B2f with ONE factor changed: + --aug_apm_p 0.3 (WebRTC NS pass on 30% of clips; --aug_apm_ns_levels left at default 6 12 18 21)
#   generated by exploop (wave B4, iteration 1) from exploop/B4/iter01/design.result.json
#  B4a = B2f + --aug_apm_p 0.3 (apm_ns arm, first of the B4 screen; rdloop B4 module b4wave sha
#    d163f934). Each training clip has a 30% chance of one pass through the WebRTC standalone
#    NoiseSuppressor (pywebrtc_audio, NS only, no HPF/AGC/AEC), level drawn from 6/12/18/21 dB. The
#    pass runs after the acoustic noise/RIR stage and before the codec, on both classes. Target:
#    B2f's weakest set, sim_heldout_v1: F1 0.8792 / 0.8827 (merge / final) with recall_bona 0.6931
#    / 0.6982 against recall_spoof 0.9900 / 0.9913 (B2f local_eval metrics.json, half_B). On that
#    set, NS-treated offline bona trails untreated bona (wave.json lever_queue apm_ns). The aim is
#    to make suppressor artefacts class-neutral so heldout bona false alarms drop. Everything else
#    is B2f's argv, 8 epochs, seed 1234.
#  Why: This is the first iteration of a pre-registered screen. wave.json lever_notes say:
#    "iterations a-c are the queued arms in this order, apm_ns -> opus_plc -> dtx_gate, each
#    exactly its `set` on top of B2f's argv". plan_snapshot.md row a is `apm_ns` `--aug_apm_p 0.3`.
#    The wave has no earlier iterations or reports, and user_notes.md has no steering notes, so the
#    queue order applies. The evidence points the same way. On the largest remaining error in B2f's
#    half_B readout (local_eval/{merge_top5,epoch_8}/metrics.json), sim_heldout_v1 is the weakest
#    set. Its F1 is 0.8792 / 0.8827 (merge / final), with recall_bona 0.6931 / 0.6982 against
#    recall_spoof 0.9900 / 0.9913. dev_online_clean F1 is 0.9760 / 0.9769. That noisy-bona deficit
#    is the recurring B2/B3 error. rdloop/B4/FINAL_SUMMARY.md says heldout carries "4.23 / 4.11 of
#    the missing WF1" and ranks apm_ns first as the best-powered contrast. Constraints: one factor
#    (`--aug_apm_p`, part of the coupled group [--aug_apm_p, --aug_apm_ns_levels]; the levels stay
#    at the trainer default [6, 12, 18, 21], as the plan specifies). The flag is in `allowed`,
#    nothing forbidden is touched, the fixed flags are unchanged, and num_epochs stays 8 (max 10).
#    batch_size stays 16 per the plan. No derived values are needed.
#  Hypothesis: B2f reads suppressor artefacts on noisy speech as synthesis. Per the wave.json
#    lever_queue, among offline sources NS-treated heldout bona trails untreated bona (69.2 vs
#    75.5, full set, final, logit gap 0.85, mostly afftdn). B2f never trained on audio that went
#    through a noise suppressor. One pass of pywebrtc_audio's NoiseSuppressor on 30% of training
#    clips, applied to both classes after the acoustic stage and before DTX/codec, should make
#    suppressor artefacts class-neutral. The effect should transfer to the unseen afftdn/anlmdn
#    suppressors in sim_heldout_v1 and raise heldout bona recall without costing spoof recall.
#  Expected signature: Mechanism (scripts/b4_dsp_slices.py --lever apm_ns, --ref = B2f's same
#    readout, offline-with-NS vs offline-without-NS bona, full set, final). 'Shown' requires all
#    of: DiD <= -0.22, bootstrap CI upper < +0.32, clip DiD >= -1.3, half-B DiD < +0.57 (final) / <
#    +0.23 (merge), and the placebo condition (NS DiD below the opus_plc and dtx_gate arms' NS DiD;
#    this can only be read once those arms exist, so it is judged at the wave SUMMARY). Secondary:
#    afftdn-vs-anlmdn DiD < -0.84. Outcome: sim_heldout_v1 F1 up >= 0.8 point from 87.92 / 88.27
#    (merge / final), driven by recall_bona rising from 69.31 / 69.82 with recall_spoof staying
#    near 99.00 / 99.13. Expected half_B WF1 delta 0 to +0.6 vs 91.98 / 92.14. Must not move:
#    dev_online_clean F1 within 0.5 of 97.60 / 97.69; sim_matched_v1 F1 down <= 0.5 from 91.22 /
#    91.24; R_spoof within 0.5 on every set; full-set offline-NS spoof misses <= 29; ep1 TrainAcc
#    within 2 of 87.36 (B2f train.log l.1).
#  Eval note: Screen arm: B2f stays the reference for the whole wave (new_best_delta 100). Compare
#    both readouts (merge_top5, epoch_8) against B2f-top5 / B2f-ep8 on the 17 sls_local17 sets with
#    a 2000-sample bootstrap CI. Run scripts/b4_dsp_slices.py --lever apm_ns on merge and final
#    with --ref = B2f's same readout. No placebo arms exist yet (opus_plc and dtx_gate come later),
#    so the per-iteration mechanism verdict is capped at 'directional' until the wave SUMMARY
#    re-runs it with --summary. Watch sim_heldout_v1 recall_bona, dev_online_clean F1 and the
#    offline-NS spoof misses.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B2f merge (91.98) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. (1) Mechanism refuted: NS DiD >= +0.32 (no better than an
#    average null retrain) AND heldout F1 delta < +0.5 on both readouts -> drop the lever. (2)
#    half_B WF1 delta < -0.5 (outside the ±0.5 band) with matched F1 down > 1.0 -> losing raw-noise
#    exposure costs more than it buys; drop, with one lower-p retry only if the mechanism was
#    'shown' without the run-anomaly flag. (3) Full-set offline-NS spoof misses > 29 on either
#    readout -> the model learned 'NS => bona'; drop. (4) Shared under-fit: ep1 TrainAcc < 85.36 or
#    ep8 TrainLoss > 0.0752 (1.5 x 0.050114, B2f train.log l.15), together with heldout bona recall
#    down -> confounded. Verdict on the wave rule: positive = merge half_B WF1 delta > +0.5 with CI
#    low > 0 and clean drop <= 0.5. Inside ±0.5 = null on the outcome; the mechanism verdict still
#    stands.
#
#   bash scripts/run_B4a.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B4a.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B4a.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B4a_qwen17_rtc_musan_loud23_cos8_lr2.5e6_apmns03_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 16
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --aug_apm_p 0.3
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b4wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
